package com.danawa.search.analysis.product.action;

import org.elasticsearch.common.io.stream.StreamInput;
import org.elasticsearch.common.io.stream.StreamOutput;
import org.elasticsearch.transport.AbstractTransportRequest;

import java.io.IOException;

/**
 * 개별 노드에 전달되는 사전 리로드 요청
 * ES 9.1.2: AbstractTransportRequest 상속 (TransportRequest가 인터페이스로 변경됨)
 */
public class ReloadDictNodeRequest extends AbstractTransportRequest {

    private String dictionaryType;

    /**
     * NodesRequest로부터 생성 - 필요한 필드만 복사
     */
    public ReloadDictNodeRequest(String dictionaryType) {
        this.dictionaryType = dictionaryType;
    }

    /**
     * ES 9.1.2: Writeable.Reader 기반 역직렬화
     */
    public ReloadDictNodeRequest(StreamInput in) throws IOException {
        super(in);
        this.dictionaryType = in.readOptionalString();
    }

    @Override
    public void writeTo(StreamOutput out) throws IOException {
        super.writeTo(out);
        out.writeOptionalString(dictionaryType);
    }

    public String getDictionaryType() {
        return dictionaryType;
    }
}

