package com.danawa.search.analysis.product.action;

import org.elasticsearch.action.FailedNodeException;
import org.elasticsearch.action.support.nodes.BaseNodesResponse;
import org.elasticsearch.cluster.ClusterName;
import org.elasticsearch.common.io.stream.StreamInput;
import org.elasticsearch.common.io.stream.StreamOutput;
import org.elasticsearch.xcontent.ToXContentObject;
import org.elasticsearch.xcontent.XContentBuilder;

import java.io.IOException;
import java.util.List;

/**
 * 클러스터 전체 노드의 사전 리로드 응답
 * ES 9.x: BaseNodesResponse로 노드별 결과 집계
 */
public class ReloadDictNodesResponse extends BaseNodesResponse<ReloadDictNodeResponse>
        implements ToXContentObject {

    public ReloadDictNodesResponse(ClusterName clusterName,
                                   List<ReloadDictNodeResponse> nodes,
                                   List<FailedNodeException> failures) {
        super(clusterName, nodes, failures);
    }

    /**
     * ES 9.x 필수: Writeable.Reader 기반 역직렬화
     */
    public ReloadDictNodesResponse(StreamInput in) throws IOException {
        super(in);
    }

    @Override
    protected List<ReloadDictNodeResponse> readNodesFrom(StreamInput in) throws IOException {
        return in.readCollectionAsList(ReloadDictNodeResponse::new);
    }

    @Override
    protected void writeNodesTo(StreamOutput out, List<ReloadDictNodeResponse> nodes) throws IOException {
        out.writeCollection(nodes);
    }

    @Override
    public XContentBuilder toXContent(XContentBuilder builder, Params params) throws IOException {
        builder.startObject();
        builder.field("cluster_name", getClusterName().value());

        // 노드별 결과
        builder.startArray("nodes");
        for (ReloadDictNodeResponse nodeResp : getNodes()) {
            builder.startObject();
            builder.field("node_id", nodeResp.getNode().getId());
            builder.field("node_name", nodeResp.getNode().getName());
            nodeResp.toXContent(builder, params);
            builder.endObject();
        }
        builder.endArray();

        // 실패한 노드
        if (hasFailures()) {
            builder.startArray("failures");
            for (FailedNodeException failure : failures()) {
                builder.startObject();
                builder.field("node_id", failure.nodeId());
                builder.field("reason", failure.getMessage());
                builder.endObject();
            }
            builder.endArray();
        }

        builder.field("all_successful", isAllSuccessful());
        builder.endObject();
        return builder;
    }

    /**
     * 모든 노드가 성공했는지 확인
     */
    public boolean isAllSuccessful() {
        return failures().isEmpty() &&
               getNodes().stream().allMatch(ReloadDictNodeResponse::isSuccess);
