package com.danawa.search.analysis.product.action;

import org.elasticsearch.action.support.nodes.BaseNodeResponse;
import org.elasticsearch.cluster.node.DiscoveryNode;
import org.elasticsearch.common.io.stream.StreamInput;
import org.elasticsearch.common.io.stream.StreamOutput;
import org.elasticsearch.xcontent.ToXContentFragment;
import org.elasticsearch.xcontent.XContentBuilder;

import java.io.IOException;

/**
 * 개별 노드의 사전 리로드 응답
 * ES 9.x: BaseNodeResponse + ToXContentFragment로 JSON 직렬화 지원
 */
public class ReloadDictNodeResponse extends BaseNodeResponse implements ToXContentFragment {

    private boolean success;
    private String message;
    private long reloadTimeMs;
    private int dictionarySize;

    /**
     * 성공 응답 생성
     */
    public ReloadDictNodeResponse(DiscoveryNode node, boolean success,
                                  String message, long reloadTimeMs, int dictionarySize) {
        super(node);
        this.success = success;
        this.message = message;
        this.reloadTimeMs = reloadTimeMs;
        this.dictionarySize = dictionarySize;
    }

    /**
     * ES 9.x 필수: Writeable.Reader 기반 역직렬화
     */
    public ReloadDictNodeResponse(StreamInput in) throws IOException {
        super(in);
        this.success = in.readBoolean();
        this.message = in.readOptionalString();
        this.reloadTimeMs = in.readVLong();
        this.dictionarySize = in.readVInt();
    }

    @Override
    public void writeTo(StreamOutput out) throws IOException {
        super.writeTo(out);
        out.writeBoolean(success);
        out.writeOptionalString(message);
        out.writeVLong(reloadTimeMs);
        out.writeVInt(dictionarySize);
    }

    @Override
    public XContentBuilder toXContent(XContentBuilder builder, Params params) throws IOException {
        builder.field("success", success);
        if (message != null) {
            builder.field("message", message);
        }
        builder.field("reload_time_ms", reloadTimeMs);
        builder.field("dictionary_size", dictionarySize);
        return builder;
    }

    public boolean isSuccess() {
        return success;
    }

    public String getMessage() {
        return message;
    }

    public long getReloadTimeMs() {
        return reloadTimeMs;
    }

    public int getDictionarySize() {
        return dictionarySize;
    }
}

