  1387→	 * 다나와 상품 FASTCAT -> ES색인 수행
  1388→	 */
  1389→	private int fastcatIndex(final RestRequest request, final NodeClient client) {
  1390→		int ret = 0;
  1391→		JSONObject jparam = new JSONObject();
  1392→		String url = request.param("url", "");
  1393→		int start = request.paramAsInt("start", 1);
  1394→		int length = request.paramAsInt("length", 1000);
  1395→		String path = request.param("path", "");
  1396→		String enc = request.param("enc", "euc-kr");
  1397→		String index = request.param("index", "");
  1398→		int flush = request.paramAsInt("flush", 50000);
  1399→		try {
  1400→			url = URLDecoder.decode(url, "utf-8");
  1401→		} catch (Exception ignore) { }
  1402→		if (!GET.equals(request.method())) {
  1403→			jparam = parseRequestBody(request);
  1404→			url = jparam.optString("url", "");
  1405→			start = jparam.optInt("start", 1);
  1406→			length = jparam.optInt("length", 1000);
  1407→			path = jparam.optString("path", "");
  1408→			enc = jparam.optString("enc", "euc-kr");
  1409→			index = jparam.optString("index", "");
  1410→			flush = jparam.optInt("flush", 50000);
  1411→		}
  1412→
  1413→		synchronized (this) {
  1414→			if (migratingThread == null || !migratingThread.running()) {
  1415→				migratingThread = new FastcatMigrateIndexer(url, start, length, path, enc, index, flush, client);
  1416→				migratingThread.start();
  1417→			} else {
  1418→				ret = migratingThread.count();
  1419→			}
  1420→		}
  1421→		return ret;
  1422→	}
