  1424→	/**
  1425→	 * 상품명 분석기를 사용하여 검색 수행
  1426→	 */
  1427→	private void search(final RestRequest request, final NodeClient client, final JSONWriter builder) {
  1428→		JSONObject jparam = new JSONObject();
  1429→		String index = request.param("index", "");
  1430→		String[] fields = request.param("fields", "").split("[,]");
  1431→		Map<String, Float> boostMap = new HashMap<>();
  1432→		String text = request.param("text", "");
  1433→		String queryString = request.param("query", "");
  1434→		String totalIndex = request.param("totalIndex", ES_INDEX_TOTALINDEX);
  1435→		int from = request.paramAsInt("from", 0);
  1436→		int size = request.paramAsInt("size", 20);
  1437→		boolean showTotal = request.paramAsBoolean("showTotal", false);
  1438→		boolean showExplain = request.paramAsBoolean("showExplain", false);
  1439→		boolean showDetail = request.paramAsBoolean("showDetail", false);
  1440→		boolean useScroll = request.paramAsBoolean("useScroll", false);
  1441→		String sortStr = request.param("sort");
  1442→		String highlightStr = request.param("highlight");
  1443→		String analyzer = request.param("analyzer", "whitespace");
  1444→		if (!GET.equals(request.method())) {
  1445→			jparam = parseRequestBody(request);
  1446→			index = jparam.optString("index", "");
  1447→			fields = jparam.optString("fields", "").split("[,]");
  1448→			text = jparam.optString("text", "");
  1449→			queryString = jparam.optString("query", "");
  1450→			totalIndex = jparam.optString("totalIndex", ES_INDEX_TOTALINDEX);
  1451→			from = jparam.optInt("from", 0);
  1452→			size = jparam.optInt("size", 20);
  1453→			showTotal = jparam.optBoolean("showTotal", false);
  1454→			showExplain = jparam.optBoolean("showExplain", false);
  1455→			showDetail = jparam.optBoolean("showDetail", false);
  1456→			useScroll = jparam.optBoolean("useScroll", false);
  1457→			sortStr = jparam.optString("sort");
  1458→			highlightStr = jparam.optString("highlight");
  1459→			analyzer = jparam.optString("analyzer","whitespace");
  1460→		}
  1461→
  1462→		for (int inx = 0; inx < fields.length; inx++) {
  1463→			String[] item = fields[inx].split("[\\^]");
  1464→			String field = item[0].trim();
  1465→			if (item.length > 1) {
  1466→				float boost = 1.0f;
  1467→				try {
  1468→					boost = Float.parseFloat(item[1].trim());
  1469→				} catch (Exception ignore) { }
  1470→				boostMap.put(field, boost);
  1471→			}
  1472→			fields[inx] = field;
  1473→		}
  1474→
  1475→		TokenStream stream = null;
  1476→		try {
  1477→			logger.trace("ANALYZE TEXT : {}", text);
  1478→			stream = ProductNameAnalyzerProvider.getAnalyzer(text, true, true, true, true, false);
  1479→			JSONObject explain = null;
  1480→			if (showExplain) {
  1481→				explain = new JSONObject();
  1482→			}
  1483→
  1484→			List<SortBuilder<?>> sortSet = null;
  1485→			if (sortStr != null && !"".equals(sortStr)) {
  1486→				logger.trace("SORT:{}", sortStr);
  1487→				sortSet = DanawaSearchQueryBuilder.parseSortSet(sortStr);
  1488→			}
  1489→
  1490→			HighlightBuilder highlight = null;
  1491→			final List<String> views = new ArrayList<>();
  1492→			final List<String> highlightTags = new ArrayList<>();
  1493→			if (highlightStr != null && !"".equals(highlightStr)) {
  1494→				logger.trace("HIGHLIGHT:{}", highlightStr);
  1495→				highlight = DanawaSearchQueryBuilder.parseHighlight(highlightStr);
  1496→				String[] preTags = highlight.preTags();
  1497→				String[] postTags = highlight.postTags();
  1498→				if (preTags.length > 0 && postTags.length > 0) {
  1499→					highlightTags.add(preTags[0]);
  1500→					highlightTags.add(postTags[0]);
  1501→				}
  1502→				for (Field field : highlight.fields()) {
  1503→					String name = field.name();
  1504→					logger.trace("FIELD:{}", name);
  1505→					if (!"_all".equals(name)) {
  1506→						views.add(name);
  1507→					}
  1508→				}
  1509→			}
  1510→
  1511→			final List<String> highlightTerms = new ArrayList<>();
  1512→			QueryBuilder query = DanawaSearchQueryBuilder.buildAnalyzedQuery(stream, fields, totalIndex, boostMap, views, highlightTerms, explain, analyzer);
  1513→			if (queryString != null && !"".equals(queryString)) {
  1514→				try {
  1515→					QueryBuilder baseQuery = DanawaSearchQueryBuilder.parseQuery(queryString);
  1516→					logger.trace("Q:{}", baseQuery);
  1517→					if (baseQuery instanceof FunctionScoreQueryBuilder) {
  1518→						QueryBuilder innerQuery = ((FunctionScoreQueryBuilder) baseQuery).query();
  1519→						if (innerQuery instanceof BoolQueryBuilder) {
  1520→							BoolQueryBuilder boolQuery = (BoolQueryBuilder) innerQuery;
  1521→							boolQuery.must().clear();
  1522→							boolQuery.must(query);
  1523→							logger.trace("Q:{}", boolQuery);
  1524→						}
  1525→						query = baseQuery;
  1526→					}
  1527→				} catch (Exception e) { 
  1528→					logger.error("", e);
  1529→				}
  1530→			}
  1531→			logger.trace("Q:{}", query);
  1532→			long total = -1;
  1533→			if (showTotal) {
  1534→				total = SearchUtil.count(client, index, query);
  1535→			}
  1536→
  1537→			boolean doScroll = !useScroll ? false : from + size > 10000;
  1538→			builder.object();
  1539→			if (showExplain) {
  1540→				builder.key("explain").value(explain);
  1541→			}
  1542→			if (showDetail) {
  1543→				builder.key("detail").value(new JSONObject(String.valueOf(query)));
  1544→			}
  1545→			if (total != -1) {
  1546→				builder.key("total").value(total);
  1547→			}
  1548→			builder.key("result").array();
  1549→
  1550→			DataModifier dataModifier = new DataModifier() {
  1551→				@Override public void modify(Map<String, Object> map) {
  1552→					for (String field : views) {
  1553→						if (map.containsKey(field)) {
  1554→							Object obj = map.get(field);
  1555→							if (obj instanceof String) {
  1556→								map.put(field, SearchUtil.highlightString(String.valueOf(obj), highlightTerms, highlightTags));
  1557→							}
  1558→						}
  1559→					}
  1560→				}
  1561→			};
  1562→			Iterator<Map<String, Object>> iter = SearchUtil.search(client, index, query, sortSet, highlight, from, size, doScroll, dataModifier);
  1563→			while (iter != null && iter.hasNext()) {
  1564→				Map<String, Object> map = iter.next();
  1565→				builder.object();
  1566→				for (String key : map.keySet()) {
  1567→					builder.key(key).value(map.get(key));
  1568→				}
  1569→				builder.endObject();
  1570→			}
  1571→			builder.endArray();
  1572→			builder.endObject();
  1573→		} catch (Exception e) {
  1574→			logger.error("", e);
  1575→		} finally {
  1576→			try { stream.close(); } catch (Exception ignore) { }
  1577→		}
  1578→	}
  1579→
  1580→	/**
  1581→	 * 상품명 분석기를 사용하여 검색 질의어 생성
  1582→	 */
  1583→	private void buildQuery(final RestRequest request, final NodeClient client, final JSONWriter builder) {
  1584→		JSONObject jparam = new JSONObject();
  1585→		String[] fields = request.param("fields", "").split("[,]");
  1586→		String totalIndex = request.param("totalIndex", ES_INDEX_TOTALINDEX);
  1587→		String text = request.param("text", "");
