  1590→			jparam = parseRequestBody(request);
  1591→			fields = jparam.optString("fields", "").split("[,]");
  1592→			totalIndex = jparam.optString("totalIndex", ES_INDEX_TOTALINDEX);
  1593→			text = jparam.optString("text", "");
  1594→			analyzer = jparam.optString("analyzer", "whitespace");
