  1642→	/**
  1643→	 * ES 사전 색인 조회용 클래스
  1644→	 * 사전 컴파일 등에 사용한다.
  1645→	 */
  1646→	public static class DictionarySource extends DictionaryRepository implements Iterator<CharSequence[]> {
  1647→		private Client client;
  1648→		private RemoteNodeClient remoteClient;
  1649→		private String index;
  1650→		private Iterator<Map<String, Object>> iterator;
  1651→		private List<Map<String, Object>> remoteResults;
  1652→		private int remoteIndex;
  1653→
  1654→		public DictionarySource(Client client, String index) {
  1655→			this.client = client;
  1656→			this.index = index;
  1657→		}
  1658→
  1659→		public DictionarySource(RemoteNodeClient remoteClient, String index) {
  1660→			this.remoteClient = remoteClient;
  1661→			this.index = index;
  1662→		}
  1663→
  1664→		@Override public Iterator<CharSequence[]> getSource(String type) {
  1665→			try {
  1666→				QueryBuilder query = QueryBuilders.matchQuery(ES_DICT_FIELD_TYPE, type.toUpperCase());
  1667→				logger.trace("QUERY:{}", query);
  1668→
  1669→				if (remoteClient != null) {
  1670→					// RemoteNodeClient를 사용한 원격 검색
  1671→					remoteResults = new ArrayList<>();
  1672→					remoteIndex = 0;
  1673→					org.elasticsearch.action.search.SearchRequest searchRequest = new org.elasticsearch.action.search.SearchRequest();
  1674→					org.elasticsearch.search.builder.SearchSourceBuilder sourceBuilder = new org.elasticsearch.search.builder.SearchSourceBuilder();
  1675→					sourceBuilder.query(query).size(10000);
  1676→					searchRequest.indices(index).source(sourceBuilder);
  1677→
  1678→					JSONObject response = remoteClient.search(searchRequest);
  1679→					if (response != null && response.has("hits")) {
  1680→						JSONObject hits = response.getJSONObject("hits");
  1681→						org.json.JSONArray hitsArray = hits.getJSONArray("hits");
  1682→						for (int i = 0; i < hitsArray.length(); i++) {
  1683→							JSONObject hit = hitsArray.getJSONObject(i);
  1684→							JSONObject source = hit.getJSONObject("_source");
  1685→							Map<String, Object> map = new HashMap<>();
  1686→							for (String key : source.keySet()) {
  1687→								map.put(key, source.get(key));
  1688→							}
  1689→							remoteResults.add(map);
  1690→						}
  1691→					}
  1692→				} else {
  1693→					// 로컬 Client를 사용한 검색
  1694→					iterator = SearchUtil.search(client, index, query, null, null, 0, -1, true, null);
  1695→				}
  1696→			} catch (Exception e) {
  1697→				logger.error("", e);
  1698→			}
  1699→			return this;
  1700→		}
  1701→
  1702→		@Override public void restore(String type, boolean ignoreCase, Set<CharSequence> wordSet) {
  1703→			if (client == null) {
  1704→				logger.warn("restore() is not supported for RemoteNodeClient");
  1705→				return;
  1706→			}
  1707→			Map<String, Object> source = null;
  1708→			BulkRequestBuilder builder = null;
  1709→			try {
  1710→				builder = client.prepareBulk();
  1711→				int inx = 0;
  1712→				for (CharSequence data : wordSet) {
  1713→					String[] words = String.valueOf(data).split(TAB);
  1714→					source = new HashMap<>();
  1715→					source.put(ES_DICT_FIELD_TYPE, type.toUpperCase());
  1716→					if (words.length == 1) {
  1717→						source.put(ES_DICT_FIELD_KEYWORD, words[0]);
  1718→					} else if (words.length == 2) {
  1719→						if (words[0].length() > 0) {
  1720→							source.put(ES_DICT_FIELD_KEYWORD, words[0]);
  1721→						}
  1722→						source.put(ES_DICT_FIELD_VALUE, words[1]);
  1723→					} else {
  1724→						source.put(ES_DICT_FIELD_KEYWORD, words[0]);
  1725→						source.put(ES_DICT_FIELD_VALUE, words[1]);
  1726→						source.put(ES_DICT_FIELD_ID, words[2]);
  1727→					}
  1728→					builder.add(client.prepareIndex(String.valueOf(index)).setSource(source));
  1729→					if (inx > 0 && inx % 1000 == 0) {
  1730→						builder.execute().actionGet();
  1731→						builder = client.prepareBulk();
  1732→					}
  1733→					inx++;
  1734→				}
  1735→				if (inx > 0) {
  1736→					builder.execute().actionGet();
  1737→				}
  1738→			} catch (Exception e) {
  1739→				logger.error("", e);
  1740→			}
  1741→		}
  1742→
  1743→		@Override public boolean hasNext() {
  1744→			if (remoteClient != null) {
  1745→				return remoteResults != null && remoteIndex < remoteResults.size();
  1746→			}
  1747→			return iterator != null && iterator.hasNext();
  1748→		}
  1749→
  1750→		@Override public CharSequence[] next() {
  1751→			Map<String, Object> data;
  1752→			if (remoteClient != null) {
  1753→				data = remoteResults.get(remoteIndex++);
  1754→			} else {
  1755→				data = iterator.next();
  1756→			}
  1757→			CharSequence id = CharVector.valueOf(data.get(ES_DICT_FIELD_ID));
  1758→			CharSequence keyword = CharVector.valueOf(data.get(ES_DICT_FIELD_KEYWORD));
  1759→			CharSequence value = CharVector.valueOf(data.get(ES_DICT_FIELD_VALUE));
  1760→			return new CharSequence[] { id, keyword, value };
  1761→		}
  1762→
  1763→		@Override public void close() { }
  1764→	}
